function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 10000) return 's needs 1 to 10000 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  if (!Number.isInteger(k) || k < 1 || k > 26) return 'k is a whole number from 1 to 26.';
  return null;
}

