function maxPartitionsAfterOperations(s, k) {
  const n = s.length;
  const memo = Array.from({ length: n }, () => new Map());
  const countBits = (mask) => {
    let count = 0;
    for (; mask !== 0; mask &= mask - 1) {
      count++;
    }
    return count;
  };

  // Partitions from index i on, when the open partition holds the letters in mask.
  const dfs = (i, mask, canChange) => {
    if (i === n) {
      return 1;
    }
    const key = mask * 2 + canChange;
    if (memo[i].has(key)) {
      return memo[i].get(key);
    }
    const own = s.charCodeAt(i) - 97;
    const first = canChange === 1 ? 0 : own;
    const last = canChange === 1 ? 25 : own;
    let best = 0;
    for (let letter = first; letter <= last; letter++) {
      const bit = 1 << letter;
      const nextCanChange = letter === own ? canChange : 0;
      const merged = mask | bit;
      if (countBits(merged) > k) {
        best = Math.max(best, 1 + dfs(i + 1, bit, nextCanChange));
      } else {
        best = Math.max(best, dfs(i + 1, merged, nextCanChange));
      }
    }
    memo[i].set(key, best);
    return best;
  };
  return dfs(0, 0, 1);
}

