function maxPartitionsAfterOperations(s, k) {
  const partitions = (t) => {
    let count = 1;
    let seen = new Set();
    for (const ch of t) {
      if (!seen.has(ch) && seen.size === k) {
        count++;
        seen = new Set();
      }
      seen.add(ch);
    }
    return count;
  };
  let best = partitions(s);
  for (let i = 0; i < s.length; i++) {
    for (const ch of 'abcdefghijklmnopqrstuvwxyz') {
      best = Math.max(best, partitions(s.slice(0, i) + ch + s.slice(i + 1)));
    }
  }
  return best;
}

