function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = 1 + Math.floor(rand() * (size === 'large' ? 26 : 6));
  const start = Math.floor(rand() * (27 - alphabet));
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 12);
  let s = '';
  for (let i = 0; i < n; i++) s += letters[start + Math.floor(rand() * alphabet)];
  const k = rand() < 0.15 ? 1 + Math.floor(rand() * 26) : 1 + Math.floor(rand() * Math.min(26, alphabet + 1));
  return [s, k];
}
